import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, DatePicker, Drawer, DrawerProps, Flex, Form, Select } from 'antd';
import cn from 'classnames';

import { EFilters, useDateFilters, useFilters } from 'features/Filters';
import { useDisableBodyScroll, useTrans } from 'shared/hooks';

import styles from './NotificationsExtendedFilters.module.scss';

interface INotificationsExtendedFiltersProps extends DrawerProps {}

export const NotificationsExtendedFilters: FC<INotificationsExtendedFiltersProps> = ({
	className,
	onClose,
	open,
	...props
}) => {
	const { t } = useTranslation();
	const {
		offersOptions,
		brandsOptions,
		offersIsFetching,
		brandsIsFetching,
		onFilterChange,
		getFilterValue,
		getALLFilterValues,
		clearFilters,
	} = useFilters();
	const { dateAfter, dateBefore, onDateChange } = useDateFilters(EFilters.CREATED_AFTER, EFilters.CREATED_BEFORE);
	const { notificationCategories } = useTrans();

	useDisableBodyScroll(!!open);

	return (
		<Drawer
			{...props}
			open={open}
			onClose={onClose}
			width={450}
			title={t('Фильтры')}
			className={cn(className, styles.extendedFilters)}>
			<Flex vertical gap={16}>
				{/*<Form.Item label={t('Период времени')} layout="vertical">
					<DatePicker.RangePicker
						style={{ width: '100%' }}
						format="DD.MM.YYYY"
						placeholder={['дд.мм.гггг', 'дд.мм.гггг']}
						value={[dateAfter, dateBefore]}
						onChange={(value) => {
							onDateChange(value?.[0] || null, EFilters.CREATED_AFTER);
							onDateChange(value?.[1] || null, EFilters.CREATED_BEFORE);
						}}
					/>{' '}
				</Form.Item>*/}

				<Flex gap={20}>
					<Form.Item label={t('Дата с')} layout="vertical" style={{ flex: 1 }}>
						<DatePicker
							format="DD.MM.YYYY"
							placeholder={t('дд.мм.гггг')}
							value={dateAfter}
							onChange={(value) => onDateChange(value, EFilters.CREATED_AFTER)}
							style={{ width: '100%' }}
						/>
					</Form.Item>

					<Form.Item label={t('Дата по')} layout="vertical" style={{ flex: 1 }}>
						<DatePicker
							format="DD.MM.YYYY"
							placeholder={t('дд.мм.гггг')}
							value={dateBefore}
							onChange={(value) => onDateChange(value, EFilters.CREATED_BEFORE)}
							style={{ width: '100%' }}
						/>
					</Form.Item>
				</Flex>

				<Form.Item label={t('Вид уведомления')} layout="vertical">
					<Select
						onChange={(value) => onFilterChange(EFilters.CATEGORY, value)}
						value={getFilterValue(EFilters.CATEGORY)}
						options={Object.keys(notificationCategories).map((key) => ({
							label: notificationCategories[key as keyof typeof notificationCategories],
							value: key,
						}))}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать вид уведомления')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Рекламодатель')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.BRAND_ID, value)}
						value={brandsIsFetching ? null : getALLFilterValues(EFilters.BRAND_ID)}
						options={brandsOptions}
						loading={brandsIsFetching}
						disabled={brandsIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать рекламодателя')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Оффер')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.OFFER_ID, value)}
						value={offersIsFetching ? null : getALLFilterValues(EFilters.OFFER_ID)}
						options={offersOptions}
						loading={offersIsFetching}
						disabled={offersIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать оффер')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Flex justify="space-between" className={styles.buttons}>
					<Button
						onClick={(e) => {
							clearFilters();
							onClose?.(e);
						}}>
						{t('Сбросить фильтры')}
					</Button>
					<Button type="primary" onClick={onClose}>
						{t('Применить')}
					</Button>
				</Flex>
			</Flex>
		</Drawer>
	);
};
