import { useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';
import { useSearchParams } from 'react-router-dom';

import { RootState } from 'app/appStore';
import {
	clearReadNotifications,
	setReadNotifications,
	useGetNotificationsCountQuery,
	useGetNotificationsListQuery,
	useReadNotifications,
} from 'entities/Notification';
import { EFilters, useFilters } from 'features/Filters';
import { EPagination } from 'features/Pagination/model/types';
import { useCommonSlice, useInfinityScroll, useInvalidateBrands, useMedia } from 'shared/hooks';

export const useNotificationsList = () => {
	const { t } = useTranslation();
	const isLg = useMedia('lg');
	const dispatch = useDispatch();
	const { getFilterValue, onFilterChange } = useFilters();
	const { appendReadNotification, setRead } = useReadNotifications();
	const [searchParams] = useSearchParams();

	const { infinityScrollOffset } = useCommonSlice();
	const offsetParam = infinityScrollOffset ? `offset=${infinityScrollOffset}` : '';

	const { data: notificationsResponse, isFetching } = useGetNotificationsListQuery(
		`${searchParams.toString()}${offsetParam && '&'}${offsetParam}`,
	);

	useInvalidateBrands();

	const notifications = notificationsResponse?.results || [];
	const total = notificationsResponse?.count || 0;

	const { data: unread } = useGetNotificationsCountQuery();
	const { readNotifications } = useSelector((s: RootState) => s.notificationsSlice);

	const loadMoreRef = useRef(null);
	const isNewFilter = getFilterValue(EFilters.READ) === 'false';

	useInfinityScroll(loadMoreRef, total, EPagination.MIN, isNewFilter ? Object.keys(readNotifications).length : 0);

	useEffect(() => {
		dispatch(clearReadNotifications());
	}, [isNewFilter, dispatch]);

	const onMarkAll = () => {
		const notificationsOnScreen = notifications.map((notification) => notification.id);
		dispatch(setReadNotifications(notificationsOnScreen));
		setRead({ ids: [] });
	};

	return {
		t,
		isLg,
		notifications,
		total,
		isFetching,
		unread,
		loadMoreRef,
		getFilterValue,
		onFilterChange,
		appendReadNotification,
		setRead,
		onMarkAll,
	};
};
