import { FC, HTMLAttributes } from 'react';

import { Flex, Tabs } from 'antd';
import cn from 'classnames';

import { NotificationCard } from 'entities/Notification';
import { EFilters, NotificationsFilters } from 'features/Filters';
import { Sort } from 'features/Sort';
import { EDefaultOptions, EMainRoutes } from 'shared/typings';
import { EmptyState, OverlayLoader } from 'shared/ui';
import { SORT_ITEMS } from 'widgets/NotificationsList';
import { useNotificationsList } from 'widgets/NotificationsList/hooks';

import styles from './NotificationsList.module.scss';

interface INotificationsListProps extends HTMLAttributes<HTMLDivElement> {}

export const NotificationsList: FC<INotificationsListProps> = ({ className, ...props }) => {
	const {
		t,
		notifications,
		total,
		isFetching,
		unread,
		loadMoreRef,
		getFilterValue,
		onFilterChange,
		appendReadNotification,
		onMarkAll,
	} = useNotificationsList();

	return (
		<Flex {...props} vertical gap={16} className={cn(className, styles.notificationsList)}>
			<Tabs
				size="small"
				tabBarStyle={{ margin: 0 }}
				items={[
					{
						key: EDefaultOptions.ALL,
						label: 'Все',
					},
					{
						key: 'false',
						label: `Непрочитанные (${unread?.unread_count})`,
					},
				]}
				onChange={(key) => onFilterChange(EFilters.READ, key)}
				activeKey={getFilterValue(EFilters.READ) || EDefaultOptions.ALL}
			/>

			<Flex vertical gap={16} align="start">
				<NotificationsFilters onMarkAll={onMarkAll} />
				<Sort sortItems={SORT_ITEMS} defaultSort={{ key: 'created_at', label: t('Сначала новые') }} />
			</Flex>

			<div className={styles.list}>
				{isFetching && <OverlayLoader />}

				{!!total &&
					notifications.map((notification) => (
						<NotificationCard
							key={notification.id}
							notification={notification}
							appendReadNotification={appendReadNotification}
						/>
					))}

				{!total && !isFetching && (
					<EmptyState
						title={t('У вас пока нет уведомлений')}
						buttonText={t('В каталог')}
						buttonTo={`/${EMainRoutes.CATALOG}`}
					/>
				)}
			</div>

			<div ref={loadMoreRef}></div>
		</Flex>
	);
};
