import { HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Badge, Button, DatePicker, Flex, Select } from 'antd';
import cn from 'classnames';

import FiltersIcon from 'assets/images/icons/filters.svg?react';
import ReadIcon from 'assets/images/icons/read.svg?react';
import { EFilters, NotificationsExtendedFilters, useDateFilters, useFilters } from 'features/Filters';
import { useMedia, useTrans } from 'shared/hooks';

import styles from './NotificationsFilters.module.scss';

export interface INotificationsFiltersProps extends HTMLAttributes<HTMLDivElement> {
	onMarkAll: () => void;
}

export const NotificationsFilters = ({ className, onMarkAll, ...props }: INotificationsFiltersProps) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const [filtersIsOpened, setFiltersIsOpened] = useState(false);
	const { getFiltersCount, onFilterChange, getFilterValue } = useFilters();
	const { dateAfter, dateBefore, onDateChange } = useDateFilters(EFilters.CREATED_AFTER, EFilters.CREATED_BEFORE);
	const { notificationCategories } = useTrans();

	return (
		<div {...props} className={cn(className, styles.filters)}>
			{/*<DatePicker.RangePicker
				size="small"
				format="DD.MM.YYYY"
				placeholder={['дд.мм.гггг', 'дд.мм.гггг']}
				value={[dateAfter, dateBefore]}
				onChange={(value) => {
					onDateChange(value?.[0] || null, EFilters.CREATED_AFTER);
					onDateChange(value?.[1] || null, EFilters.CREATED_BEFORE);
				}}
			/>*/}

			<DatePicker
				lang="en"
				format="DD.MM.YYYY"
				size="small"
				placeholder={t('Дата с')}
				value={dateAfter}
				onChange={(value) => onDateChange(value, EFilters.CREATED_AFTER, true, false)}
			/>

			<DatePicker
				format="DD.MM.YYYY"
				size="small"
				placeholder={t('Дата по')}
				value={dateBefore}
				onChange={(value) => onDateChange(value, EFilters.CREATED_BEFORE, true, true)}
			/>

			<Select
				size="small"
				onChange={(value) => onFilterChange(EFilters.CATEGORY, value)}
				value={getFilterValue(EFilters.CATEGORY)}
				options={Object.keys(notificationCategories).map((key) => ({
					label: notificationCategories[key as keyof typeof notificationCategories],
					value: key,
				}))}
				showSearch
				optionFilterProp="label"
				placeholder={t('Выбрать вид уведомления')}
				allowClear
			/>

			<Flex vertical={isMd} justify="space-between" gap={12}>
				<Button size="small" icon={<FiltersIcon />} onClick={() => setFiltersIsOpened(true)}>
					{t('Фильтры')} <Badge size="small" count={getFiltersCount()} />
				</Button>
				<Button size="small" type="text" icon={<ReadIcon />} iconPosition="end" onClick={onMarkAll}>
					{t('Прочитать все')}
				</Button>
			</Flex>

			<NotificationsExtendedFilters open={filtersIsOpened} onClose={() => setFiltersIsOpened(false)} />
		</div>
	);
};

export default NotificationsFilters;
